import './session.js';
import { entryMarkup,mountWeightEntry,clearWeightDraft,editWeight } from './journal-entry.js';
import { journalView } from './journal-view.js';
const root=document.querySelector('#journal-root'),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat('en-AU',{maximumFractionDigits:2}),kg=v=>Number.isFinite(v)?nf.format(v):'—',signed=v=>Number.isFinite(v)?(v>0?'+':'')+nf.format(v):'—';
const day=value=>new Date(value+'T12:00:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}),dateMs=d=>Date.parse(d+'T12:00:00Z');
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg>',logo='<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M3 25 11 7h5L8 25m9 0 8-18h4l-8 18"/></svg>';
let data,windowChoice='90',selection=0,chart,preview,busy=false,animation,motion=true,shown=12,writingWeight=false;
try{motion=localStorage.getItem('mfa-visual-motion')!=='off';}catch{}
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
async function api(url,options){const response=await fetch(url,{cache:'no-store',...options});if(response.status===401){location.replace('/sign-in.html');throw new Error('Sign in to open your journal.');}let value;try{value=await response.json();}catch{throw new Error('The service could not respond. Try again.');}if(!response.ok)throw new Error(value.error||'The request could not finish.');return value;}
function graph(){const points=data.points;if(!points.length){chart=null;return '<div class="jr-empty"><span class="tr-eyebrow">Your first reading starts the line</span><h2>Your next reading<br>starts the line.</h2><p>Log your first weigh-in or import your MASS history. The chart will use your actual recorded values.</p></div>';}
 const w=innerWidth<1000?500:900,left=72,right=w-36;const axisDay=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-AU',{day:'numeric',month:'short',timeZone:'UTC'});const values=points.map(p=>p.kg),min=Math.floor((Math.min(...values)-.3)*2)/2,max=Math.ceil((Math.max(...values)+.3)*2)/2,start=dateMs(points[0].date),end=Math.max(dateMs(data.anchor),dateMs(points.at(-1).date)),x=p=>left+(dateMs(p.date)-start)/(end-start||86400000)*(right-left),y=value=>28+(max-value)/(max-min||1)*270;
 const path=field=>{let previous;return points.map(p=>{const value=p[field];if(value===null){previous=null;return '';}const command=previous&&dateMs(p.date)-dateMs(previous.date)<=7*86400000?'L':'M';previous=p;return `${command}${x(p).toFixed(2)},${y(value).toFixed(2)}`;}).join(' ');};chart={x,y,width:w};selection=Math.min(selection,points.length-1);const selected=points[selection];
 return `<div class="jr-chart-top"><div><span class="tr-eyebrow">Recorded body weight</span><div class="jr-selected-value"><strong id="selected-kg">${kg(selected.kg)}</strong><span>kg</span></div><p id="selected-date">${day(selected.date)} · ${selected.readings} reading${selected.readings===1?'':'s'}</p></div><div class="jr-chart-legend"><span><i></i>Daily value</span><span><i></i>7-day mean</span></div></div><div class="jr-chart-frame"><svg viewBox="0 0 ${w} 350" aria-hidden="true" style="--jr-axis:${w===500?20:22}px"><defs><linearGradient id="weight-line" x1="0" x2="1"><stop stop-color="var(--color-highlight)"/><stop offset="1" stop-color="var(--color-accent)"/></linearGradient></defs>${[min,(min+max)/2,max].map(v=>`<path class="jr-grid" d="M${left} ${y(v)}H${right}"/><text x="4" y="${y(v)+5}">${kg(v)}</text>`).join('')}<path class="jr-weight-line" d="${path('kg')}"/><path class="jr-mean-line" d="${path('mean7')}"/>${points.map(p=>`<circle class="jr-reading-dot" cx="${x(p)}" cy="${y(p.kg)}" r="3"/>`).join('')}<g id="chart-cursor"><path class="jr-cursor-line" d="M${x(selected)} 20V308"/><circle cx="${x(selected)}" cy="${y(selected.kg)}" r="7"/></g><text x="${left}" y="342">${axisDay(points[0].date)}</text><text x="${right}" y="342" text-anchor="end">${axisDay(points.at(-1).date>data.anchor?points.at(-1).date:data.anchor)}</text></svg></div><label class="jr-slider-label" for="reading-cursor">Inspect a recorded day <span id="mean-readout">${selected.mean7===null?'Mean needs 3 recorded days within 7 days':'7-day mean: '+kg(selected.mean7)+' kg'}</span></label><input id="reading-cursor" type="range" min="0" max="${points.length-1}" value="${selection}" step="1" aria-valuetext="${day(selected.date)}, ${kg(selected.kg)} kilograms"><p class="jr-chart-note">Axis follows your recorded range. Gaps longer than seven days are left open.</p>`;
}
function updateCursor(){const point=data.points[selection];if(!point||!chart)return;document.querySelector('#selected-kg').textContent=kg(point.kg);document.querySelector('#selected-date').textContent=day(point.date)+` · ${point.readings} reading${point.readings===1?'':'s'}`;document.querySelector('#mean-readout').textContent=point.mean7===null?'Mean needs 3 recorded days within 7 days':'7-day mean: '+kg(point.mean7)+' kg';const slider=document.querySelector('#reading-cursor');slider.value=selection;slider.setAttribute('aria-valuetext',day(point.date)+', '+kg(point.kg)+' kilograms');const cursor=document.querySelector('#chart-cursor');cursor.querySelector('path').setAttribute('d',`M${chart.x(point)} 20V308`);cursor.querySelector('circle').setAttribute('cx',chart.x(point));cursor.querySelector('circle').setAttribute('cy',chart.y(point.kg));}
function renderReview(message=''){const count=kind=>preview.counts[kind];document.querySelector('#review-content').innerHTML=`<h2 id="review-title" tabindex="-1">Bring this history in?</h2><p class="jr-import-name">${escape(preview.name)}</p><p>${preview.dateRange?day(preview.dateRange[0])+' → '+day(preview.dateRange[1]):'No dated rows'} · exported ${new Date(preview.exportedAt).toLocaleDateString('en-AU')}</p><div class="jr-preview-counts">${[['weights','Weigh-ins'],['sessions','MASS sessions']].map(([key,label])=>`<div><strong>${label}</strong><dl>${[['added','New'],['updated','Updated'],['deleted','Deletion markers'],['unchanged','Unchanged'],['older','Older versions skipped'],['excluded','Before July 2026']].map(([field,title])=>`<div><dt>${title}</dt><dd>${count(key)[field]||0}</dd></div>`).join('')}</dl></div>`).join('')}</div><p>After import: ${preview.result.weights} active MASS weight readings and ${preview.result.sessions} active MASS sessions. Manual weigh-ins stay separate. Missing rows in this file will not delete existing history.</p><p class="jr-section-note">Only weight and session records enter the journal. The original file is kept privately for backup.</p>${message?`<p role="alert" class="tr-error">${escape(message)}</p>`:''}${preview.overlapDates?.length&&!preview.duplicate?`<div class="je-same-day"><p>MASS and manual readings overlap on ${preview.overlapDates.length} date(s). They stay separate; the chart averages the readings on each date.</p><label><input type="checkbox" id="confirm-import-overlap" ${preview.confirmSameDay?'checked':''}>Keep both sources as separate readings</label></div>`:''}<button class="primary-button" id="commit-import" ${busy?'disabled':''}>${busy?'Saving your history…':'Import records'}</button>${message?'<button class="secondary-button" id="refresh-import-review">Refresh this review</button>':''}<button class="text-button" id="cancel-import" ${busy?'disabled':''}>Cancel</button>`;document.querySelector('#confirm-import-overlap')?.addEventListener('change',e=>preview.confirmSameDay=e.target.checked);document.querySelector('#commit-import').addEventListener('click',commitImport);document.querySelector('#cancel-import').addEventListener('click',closeReview);document.querySelector('#refresh-import-review')?.addEventListener('click',async()=>{if(busy)return;busy=true;const prior=preview;try{const next=await api('/api/mass/preview',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:prior.raw});preview={...next,name:prior.name,raw:prior.raw};busy=false;renderReview();}catch(e){busy=false;renderReview(e.message);}});document.querySelector('#close-review').disabled=busy;}

function render(animateView=true){
 animation?.revert();document.body.dataset.hasJournal=String(data.entries.length>0);
 root.innerHTML=journalView({data,windowChoice,graph,entry:entryMarkup(data),kg,signed,day,escape,arrow,logo,motion:motion&&!reduced.matches,shown});
 bind();if(animateView)animate();
}
async function load(window='90',animateView=true){const next=await api('/api/journal?window='+window);data=next;windowChoice=window;selection=Math.max(0,data.points.length-1);render(animateView);}
function error(message){document.querySelector('#import-error').textContent=message;}
function notice(message){const node=document.querySelector('#journal-status');node.textContent=message;node.tabIndex=-1;node.focus({preventScroll:true});}
function setBusy(value){writingWeight=value;document.querySelectorAll('[data-window],#choose-file,#more-readings').forEach(b=>b.disabled=value);}
function bind(){
 document.querySelector('#reading-cursor')?.addEventListener('input',e=>{selection=Number(e.target.value);updateCursor();});
 document.querySelectorAll('[data-date]').forEach(b=>b.addEventListener('click',()=>{selection=data.points.findIndex(p=>p.date===b.dataset.date);updateCursor();document.querySelector('#reading-cursor')?.focus({preventScroll:true});}));
 document.querySelectorAll('[data-window]').forEach(b=>b.addEventListener('click',async()=>{if(writingWeight||b.getAttribute('aria-pressed')==='true')return;document.querySelectorAll('[data-window]').forEach(x=>x.disabled=true);try{await load(b.dataset.window,false);document.querySelector(`[data-window="${windowChoice}"]`).focus({preventScroll:true});}catch(e){setBusy(false);error(e.message);}}));
 document.querySelector('#choose-file')?.addEventListener('click',()=>document.querySelector('#mass-file').click());document.querySelector('#mass-file')?.addEventListener('change',previewFile);
 document.querySelector('#close-review').addEventListener('click',closeReview);document.querySelector('#mass-review').addEventListener('cancel',e=>{if(busy)e.preventDefault();else closeReview();});
 document.querySelector('#motion').addEventListener('click',()=>{motion=!motion;try{localStorage.setItem('mfa-visual-motion',motion?'on':'off');}catch{}animation?.revert();setMotion();});
 document.querySelector('#more-readings')?.addEventListener('click',()=>{shown+=20;render(false);document.querySelector('#more-readings')?.focus({preventScroll:true});});
 for(const button of document.querySelectorAll('[data-edit-weight],[data-restore-weight]'))button.addEventListener('click',()=>{
  if(writingWeight)return;const restore=Boolean(button.dataset.restoreWeight),entry=(restore?data.removed:data.entries).find(r=>r.entryKey===(button.dataset.editWeight||button.dataset.restoreWeight)&&r.source==='manual');
  if(!entry)return;editWeight(entry,data);render(false);document.querySelector('#quick-log').scrollIntoView({block:'center',behavior:reduced.matches?'instant':'smooth'});document.querySelector('#weight-kg').focus({preventScroll:true});
 });
 mountWeightEntry({data,request:api,onBusy:setBusy,onReset(){render(false);document.querySelector('#weight-kg')?.focus({preventScroll:true});},refreshData:()=>api('/api/journal?window='+windowChoice),async onSaved(message){await load(windowChoice,false);notice(message);}});
 const svg=document.querySelector('.jr-chart-frame svg');svg?.addEventListener('click',e=>{const rect=svg.getBoundingClientRect(),position=(e.clientX-rect.left)/rect.width*chart.width;let nearest=0,best=Infinity;data.points.forEach((p,i)=>{const d=Math.abs(chart.x(p)-position);if(d<best){best=d;nearest=i;}});selection=nearest;updateCursor();});
 setMotion();
}
function setMotion(){const enabled=motion&&!reduced.matches;document.body.dataset.motion=enabled?'on':'off';document.querySelector('#motion').setAttribute('aria-pressed',String(enabled));document.querySelector('#motion span').textContent=enabled?'on':'off';}
function animate(){if(!motion||reduced.matches||!window.gsap)return;animation=gsap.context(()=>{gsap.from('.jr-title,.jr-entry-panel',{opacity:0,y:14,duration:.55,stagger:.08,ease:'power3.out',clearProps:'all'});const path=document.querySelector('.jr-weight-line');if(path){const length=path.getTotalLength();gsap.fromTo(path,{strokeDasharray:length,strokeDashoffset:length},{strokeDashoffset:0,duration:.9,ease:'power2.out',clearProps:'strokeDasharray,strokeDashoffset'});}});}
matchMedia('(max-width:999px)').addEventListener('change',()=>{if(data&&!writingWeight&&!busy)render(false);});
reduced.addEventListener('change',()=>{animation?.revert();if(data)setMotion();});
async function previewFile(e){
 const file=e.target.files[0];if(!file)return;e.target.value='';error('');const button=document.querySelector('#choose-file');button.disabled=true;document.querySelector('#import-status').textContent='Reading your MASS backup…';
 try{const max=data.importLimitMB||10;if(file.size>max*1024*1024)throw new Error('Choose a MASS export smaller than '+max+' MB.');const raw=await file.arrayBuffer();preview=await api('/api/mass/preview',{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:raw});preview.name=file.name;preview.raw=raw;renderReview();document.querySelector('#mass-review').showModal();document.querySelector('#review-title').focus({preventScroll:true});document.querySelector('#import-status').textContent='Ready to review. No records saved yet.';}
 catch(e){error(e.message);document.querySelector('#import-status').textContent='Import did not start. Your saved data is unchanged.';}finally{button.disabled=false;}
}
function closeReview(){if(busy)return;document.querySelector('#mass-review').close();preview=null;document.querySelector('#choose-file')?.focus();}
async function commitImport(){
 if(busy||!preview)return;if(preview.overlapDates?.length&&!preview.duplicate&&!preview.confirmSameDay){renderReview('Confirm that overlapping source readings should stay separate.');document.querySelector('#confirm-import-overlap').focus();return;}busy=true;renderReview();
 try{const options=data.cloud?{headers:{'Content-Type':'application/octet-stream','x-journal-revision':String(preview.headRevision),'x-import-hash':preview.hash,'x-confirm-same-day':preview.confirmSameDay?'1':'0'},body:preview.raw}:{headers:{'Content-Type':'application/json'},body:JSON.stringify({token:preview.token})};
  const result=await api('/api/mass/commit',{method:'POST',...options});document.querySelector('#mass-review').close();busy=false;preview=null;await load(windowChoice,false);
  const changed=Object.values(result.counts).reduce((n,c)=>n+c.added+c.updated+c.deleted,0);const message=result.duplicate||!changed?'Already up to date. No duplicate records added.':'MASS history saved '+(data.cloud?'to your private account.':'on this computer.');document.querySelector('#import-status').textContent=message;notice(message);
 }catch(e){busy=false;if(preview)renderReview(e.message);else error(e.message);}
}
try{await load();}catch(e){root.innerHTML=`<main class="training-loading"><h1>Your journal couldn’t load.</h1><p>${escape(e.message)}</p><button class="primary-button" id="retry">Retry</button><a href="/training" class="text-button">Back to training</a></main>`;document.querySelector('#retry').addEventListener('click',()=>location.reload());}
